values ('article-open-weight', 'articles', 5, 'Açık Kaynak vs Açık Ağırlık makalesi', 'Open Source vs Open Weight article', '"Yapay Zeka Dünyasında Kavram Karmaşası: Open Source Model vs Open Weight Model" yazısı, açık kaynak modellerle yalnızca ağırlıkları paylaşılan modeller arasındaki farkı açıklıyor.', '"Confusion of Concepts in AI: Open Source Model vs Open Weight Model" explains the difference between truly open-source models and models that only share their weights.', array['acik', 'agirlik', 'weight', 'open', 'kaynak', 'source']::text[], '[{"label":{"tr":"Makaleyi oku","en":"Read article"},"href":"https://medium.com/@osmanbugrabolat/yapay-zeka-d%C3%BCnyas%C4%B1nda-kavram-karma%C5%9Fas%C4%B1-open-source-model-vs-open-weight-model-32ccccd2f0f5"}]'::jsonb, array['articles-overview', 'article-mcp']::text[])
