values ('article-ai-future', 'articles', 5, 'Yapay Zeka makalesi ne anlatıyor?', 'What is the AI article about?', '"Yeni Geleceğin Başlangıcı: Yapay Zeka" yazısı, yapay zekânın ne olduğunu ve geleceği nasıl şekillendirdiğini anlatan bir giriş yazısı.', '"The Beginning of a New Future: Artificial Intelligence" is an introductory piece on what AI is and how it is shaping the future.', array['gelecek', 'gelecegin', 'future']::text[], '[{"label":{"tr":"Makaleyi oku","en":"Read article"},"href":"https://medium.com/@osmanbugrabolat/yeni-gelece%C4%9Fin-ba%C5%9Flang%C4%B1c%C4%B1-yapay-zeka-9313cb13e31f"}]'::jsonb, array['articles-overview', 'skills-ai-ml']::text[])
